contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log, uint val) public payable {
        bool setLogReverted;
        c.SetLogFile(log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setLogReverted = true;
        } else {
            setLogReverted = false;
        }

        uint minSumAfterLog = c.MinSum(); if (__ESBMC_reverted()) return;

        bool setMinReverted;
        c.SetMinSum(val); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setMinReverted = true;
        } else {
            setMinReverted = false;
        }

        uint minSumAfterMin = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(
            !setLogReverted &&
            !setMinReverted &&
            minSumAfterMin == val
        );
    }

    receive() external payable {}
}

